statement:
\begin{lemma}[Preservation of the route]
 \label{lem:routing}
For every outcome in \(\xi\), every \(i<M\), every \(n\in W_{e_i}\),
and every \(t\in[1,2]\), the actual root path of \(y_n(t)\) reaches
\(U\) and rejects children \(1,\ldots,i-1\) there.
In particular,
\begin{equation}
 \label{eq:local-hit}
 Q_i(y_n(t))=1
 \quad\Longrightarrow\quad y_n(t)\in B.
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:representatives}
Fix a stable center $x$ and an atom $\xi$ of the full center exposure
$\mathcal F_x$ in \eqref{eq:center-exposure} on which the first-default node $U$ exists.  Let $h$ be
its height, put $r=r_h$, and write
\[
 e_i=(U,i),\qquad b_i^*=b_{e_i}^*,\qquad 1\le i<M.
\]
There is a finite set $\mathcal R(x,U)\subset[1,2]$, depending only on
$x,U$ and the deterministic windows, with
\begin{equation}
 |\mathcal R(x,U)|\le20Mr\bigl(1+2^{2r+2}\bigr),
 \label{eq:representative-count}
\end{equation}
such that the following holds for the local predicates $Q_i$ in
\eqref{eq:local-predicate}, for every realization of the tables
consistent with $\xi$.  For each $t\in[1,2]$, some
$t'\in\mathcal R(x,U)$ satisfies
\begin{equation}
 Q_i(x+t2^{-n})=Q_i(x+t'2^{-n})
 \quad\text{for all }1\le i<M\text{ and }n\in W_{e_i}.
 \label{eq:representative-agreement}
\end{equation}
\end{lemma}

\begin{proposition}\label{prop:raw-failure}
For every fixed stable center $x$,
\begin{equation}
 \Pbb\bigl(\exists t\in[1,2]\ \forall n\in\mathcal N:
 x+t2^{-n}\notin B\bigr)\le2p.
 \label{eq:raw-failure}
\end{equation}
\end{proposition}

\begin{lemma}[The fixed-scale estimate]
\label{lem:fixed-scale}
Fix a stable center \(x\) and an atom \(\xi\) of the center-exposure
sigma-field \(\mathcal F_x\) in \eqref{eq:center-exposure}, on
which the first default node \(U\) exists.  Let \(h\) be its height,
put \(r=r_h\), and use the local predicates \(Q_i\) for
\(e_i=(U,i)\), \(1\le i<M\), defined in \eqref{eq:local-predicate}, with \(y_n(t)=x+t2^{-n}\). For every fixed
\(t\in[1,2]\),
\begin{equation}
 \Pbb\left(
 Q_i(y_n(t))=0
 \text{ for all }1\le i<M,\ n\in W_{e_i}
 \,\middle|\,\xi
 \right)
 =(1-p/2)^{(M-1)r}.
 \label{eq:fixed-scale-miss}
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:stable}
The set $G$ is measurable and $1$-periodic, and $\rho(G^c)<p$.
For every $x\in G$, every window $W_e$, every $n\in W_e$, every
$t\in[1,2]$, and every window $W_f$ earlier than $W_e$,
\begin{equation}
 J_{b_f}(x+t2^{-n})=J_{b_f}(x).
 \label{eq:stable-keys}
\end{equation}
These assertions include centers lying on grid boundaries.
\end{lemma}

\begin{proposition}\label{prop:periodic}
For every $p\in(0,1)$, there is an open $1$-periodic set $H\subseteq\R$
with $\rho(H)\le6p$ such that
\begin{equation}\label{eq:periodic-hitting}
 \text{for every }x\in\R\text{ and }t\in[1,2],
 \quad x+tq^n\in H\text{ for some integer }n\ge1.
\end{equation}
\end{proposition}

\begin{lemma}[Span of an edge and its child subtree]\label{lem:window-span}
If $e=(P,i)$ leaves a vertex of height $h$, then
\begin{equation}\label{eq:window-span}
 b_e^*-a_e+1\le2r_h.
\end{equation}
\end{lemma}

\begin{lemma}[Stability and earlier keys]\label{lem:stability}
The set $\mathcal S$ is measurable and $1$-periodic, and
\[
 \rho(\R\setminus\mathcal S)\le4Kc\,q^{g+1}.
\]
If $x\in\mathcal S$, $n\in W_e$, and $t\in[1,2]$, then every edge $f$
preceding $e$ in preorder satisfies
\begin{equation}\label{eq:stable-keys}
 J_{b_f}(x+tq^n)=J_{b_f}(x).
\end{equation}
\end{lemma}

\begin{lemma}[Separation within one window]\label{lem:separation}
Fix an edge $e$, a center $x\in\R$, and a scale $t\in[1,2]$.  The points
\[
 \{x\}\ \cup\ \{x+tq^n:n\in W_e\}
\]
have pairwise distinct keys under $J_{b_e}$.  They also have pairwise
distinct keys under every $J_b$ with $b\ge b_e$.
\end{lemma}

\begin{lemma}[Mean density]
 \label{lem:density}
The random set \(B\) in \eqref{eq:random-set} satisfies
\(\E\rho(B)=p\).
\end{lemma}

\begin{lemma}[Preservation of routing]
 \label{lem:routing}
Fix a stable center \(x\) and an atom \(\xi\) of \(\mathcal F_x\)
on which the first default vertex \(U\) exists. For every outcome in
\(\xi\), every \(i<M\), every \(n\in W_{e_i}\), and every
\(t\in[1,2]\), the route of \(y_n(t)\) reaches \(U\) and rejects its
children \(1,\ldots,i-1\). Consequently,
\begin{equation}
 \label{eq:local-hit}
 Q_i(y_n(t))=1\quad\Longrightarrow\quad y_n(t)\in B.
\end{equation}
\end{lemma}

\begin{lemma}[Independent tests]
 \label{lem:independent-tests}
Fix a stable center \(x\) and an atom \(\xi\) of \(\mathcal F_x\)
on which the first default vertex \(U\) exists. Let \(h\) be its
height and \(r=r_h\), and define \(Q_i\) by \eqref{eq:local-test}.
For every fixed \(t\in[1,2]\),
\begin{equation}
 \label{eq:test-failure}
 \Prob\left(
 Q_i(y_n(t))=0\text{ for all }i<M,\ n\in W_{e_i}
 \,\middle|\,\xi\right)
 =(1-p/2)^{(M-1)r}.
\end{equation}
\end{lemma}

\begin{lemma}[Conditional control of all normalized scales]
\label{lem:conditional-scales}
Fix $p\in(0,1)$ and the construction parameters $M,d,g,r_0$ of
Sections~\ref{sec:windows} and~\ref{sec:routing}.
Let $x\in\mathcal S$ be a stable center, and let $\xi$ be an atom of
the center-exposure field $\mathcal F_x$ on which the route of $x$
uses a default edge.  If its first default occurs at a vertex $U$ of
height $h$, put $r=r_h$ and
\begin{equation}\label{eq:scale-count}
 D_{M,q}(r)=4+2(M-1)r\bigl(1+2c q^{-2r}\bigr).
\end{equation}
Then
\begin{equation}\label{eq:conditional-scales}
 \Prob\!\left(
  \exists t\in[1,2]\ \forall n\in\mathcal N:\
  x+tq^n\notin B\ \middle|\ \xi
 \right)
 \le D_{M,q}(r)e^{-p(M-1)r/2}.
\end{equation}
\end{lemma}
